import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"28、【大過】 巽下兌上","description":"周易尚氏學 - 28、【大過】 巽下兌上","frontmatter":{"title":"28、【大過】 巽下兌上","description":"周易尚氏學 - 28、【大過】 巽下兌上"},"headers":[],"relativePath":"classics/shangshi/033.md","filePath":"classics/shangshi/033.md"}'),s={name:"classics/shangshi/033.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_28、【大過】-巽下兌上" tabindex="-1">28、【大過】 巽下兌上 <a class="header-anchor" href="#_28、【大過】-巽下兌上" aria-label="Permalink to “28、【大過】 巽下兌上”">​</a></h1><p>過失也。謂中四陽隱於陰中。失其用也。說文棟極也。爾雅棟謂之俘（左木）。郭璞雲。屋脊也。易林以坎為棟為屋極。大過本大坎也。坎以中爻為棟。大過以三四為棟。橈。釋文雲。由折也。兌毀折。巽隕落。故棟橈。以易理言。朋承陽則利。利有攸往。應指初。升初六曰允升。曰上合志。大過初與升初同。而四有應。故往利也。虞翻知陽爻無利往者。乃謂二變應五故利往。如虞說。傳雲棟橈本末弱。本謂初。初亦失位可變也。尚何弱這有哉。乃自宋朱震以來。即承其說。甚矣其不思也。</p><p>彖曰。大過。大者過也。棟撓？？。本末弱也。剛過而中。巽而說行。利有攸往。乃亨。大過之時大矣哉。</p><p>卦氣圖。大過十月卦。閉塞成冬。故曰大過時。</p><p>大過過字。彖傳未明釋。後儒或以過往為說。先天位兌左巽右中過乾或以過盛為說。此說尤不協。四陽五陽卦多矣。胡此獨盛皆有可疑。愚按太玄擬大過為失。言四陽為陰所錮。失其用也。故漢人皆謂大過為死卦。易林明夷之大過雲。言笑未畢。憂來暴卒。又大壯之大過雲。道絕不通。商旅失意。又既濟之大過雲。身加檻纜。囚繫縛束。太玄又擬為劇。劇甚也。病也。皆謂陰大賊陽。陽失其用。與易林說合若符契。</p><p>象曰。澤滅木。大過。君子以獨立不懼。通世無悶。</p><p>不曰澤中有木。而曰澤滅木。此漢人死卦之說所由來也。滅者人之所懼。君子則獨立不懼。巽為寡故曰獨。乾為惕故曰懼。兌悅故不懼。陽陷陰中。陰伏不出。故曰遁世。過世宜有憂矣。乃君子則適世無悶。以兌悅在終也。大象每反以見義。此亦其一也。</p><p>初六。籍用白茅。無咎。</p><p>藉薦也。凡以物承物曰藉。曲禮執玉。其有藉者則裼。無籍者則襲。注籍藻也。疏執玉必有藻以承玉。巽為伏。初在下。故曰籍。巽為白為茅。茅柔物。初陰故曰藉用白茅。又祭時籍茅於地。用以縮酒。而巽為漏。井九三雍（下兀）敝漏於象尤切。</p><h3 id="象曰。藉用白茅。桑在下也。" tabindex="-1">象曰。藉用白茅。桑在下也。 <a class="header-anchor" href="#象曰。藉用白茅。桑在下也。" aria-label="Permalink to “象曰。藉用白茅。桑在下也。”">​</a></h3><p>初柔在下。承陽故無咎</p><p>九二。枯楊生梯。老夫得其女妻。無不利。</p><p>巽。為楊。為隕落。為枯。易林泰之威雲。老楊日衰。條多枯枝。噬嗑之否雲。朽根枯樹。是以鹹否互巽為枯也。梯鄭作美。木更生。按詩衛風手如柔荑。傳雲。如荑之新生。然則荑為木新生之條。蓋弟（左禾）荑同字。莊子知北遊雲。在荑稗。釋文雲美本又作弟（左禾）。是其證。乾為生。巽為木。巽柔。故曰枯楊生弟（左禾）。伏震為老夫。巽為女妻。女妻者。少妻。二下孚於陰。故無不利。巽為利也。易林遇震即曰老夫。遇巽即曰少齊。曰少姬。本此也。詳焦氏易詁。虞翻以乾老為枯。豈知乾實雖老不枯。又以乾老為老夫。兌為少女。創二應上初應五之例。以圓其說。是貞悔不必拘。而應與常例可破也。乃清儒翕然從之。異已。只俞樾以虞說為不通。知用旁通。打破二千年之謬誤。為功甚偉。特又以大過二五與頤二五相升降以取象。豈知巽即為少妻。兌即為老婦。易林有明徵。不必如是穿鑿也。故夫象一失傳。雖以俞氏之深識旁通。且洞明陽順陰逆之理。亦無如何也。</p><h3 id="象曰。老夫女妻。過以相與也。" tabindex="-1">象曰。老夫女妻。過以相與也。 <a class="header-anchor" href="#象曰。老夫女妻。過以相與也。" aria-label="Permalink to “象曰。老夫女妻。過以相與也。”">​</a></h3><p>過以相與。言其不當。非謂初可過四應五。二可過五應上也。</p><p>九三。棟橈。兇。</p><p>初爻本弱。故楝橈。上雖有應。然四五皆陽。得敵。九三不能應上。故曰不可以有輔。</p><h3 id="象曰。棟橈之兇。不可以有輔也。" tabindex="-1">象曰。棟橈之兇。不可以有輔也。 <a class="header-anchor" href="#象曰。棟橈之兇。不可以有輔也。" aria-label="Permalink to “象曰。棟橈之兇。不可以有輔也。”">​</a></h3><p>輔。佐助也。</p><p>九四。棟隆。吉。有它吝</p><p>巽為高。四居巽上。故曰棟隆吉。有它吝者。言四應在初。四若它往應之。則為二三所忌。而致吝矣。四與三不同。三與初同體。本弱無如何。若四隻不與初應。則吉也。</p><h3 id="象曰。棟隆之吉。不橈乎下也。" tabindex="-1">象曰。棟隆之吉。不橈乎下也。 <a class="header-anchor" href="#象曰。棟隆之吉。不橈乎下也。" aria-label="Permalink to “象曰。棟隆之吉。不橈乎下也。”">​</a></h3><p>不橈乎下。即不應初。</p><p>九五。枯楊生華。老婦得其士夫。無咎無譽。</p><p>兌為反巽。故仍曰枯楊。兌為華。易林否之成雲。華落實槁。以鹹上兌為華。需之剝雲。老婦亡夫。以剝伏兌為老婦。又否之中。孚老妾據機。以中孚下兌為老妾。伏艮為士夫。故曰老婦得其士夫。五比陰志行故無咎。下無應。故無譽。虞翻以五應初巽為老婦。易無此例也。蓋易有伏象。伏即旁通。即對象。人知之。而旁通之原理。鮮能明之。文言云。旁通情也。情者感也。言陰陽不能相離也。故夫茅茹坤象也。泰初爻亦言之。雲雨坤坎象也。小畜亦言之。否初言茅茹。小過言云雨。則用正象。易林本之。正伏象常不分。略如見一男子。可推知其家必有婦。見一婦人。可推知其家必有夫也。然非以夫為婦。以婦為夫。使男女無別也。易繫辭取象可用伏。而義則正也。彼夫王引之譏虞翻用旁通。致陰陽無別。是皆於旁通情。情字失詁。故於易理隔閡如斯也。大過老夫士夫。皆在對象。而自荀虞以來。皆苦於本象求之。胡有得乎。</p><h3 id="象曰。枯楊生華。何可久也。老婦士夫。亦可且也。" tabindex="-1">象曰。枯楊生華。何可久也。老婦士夫。亦可且也。 <a class="header-anchor" href="#象曰。枯楊生華。何可久也。老婦士夫。亦可且也。" aria-label="Permalink to “象曰。枯楊生華。何可久也。老婦士夫。亦可且也。”">​</a></h3><p>匹配失宜。故可醜。</p><p>上六。過涉滅頂。兇。無咎。</p><p>乾為首。故為頂。澤水在上。故滅頂。與比之無首義同也。滅頂則死故兇。大過之為死卦在此。然上六當位有應。兇則有之。咎則無也。故象曰不可咎。</p><h3 id="象曰。過涉之兇。不可咎也。" tabindex="-1">象曰。過涉之兇。不可咎也。 <a class="header-anchor" href="#象曰。過涉之兇。不可咎也。" aria-label="Permalink to “象曰。過涉之兇。不可咎也。”">​</a></h3><p>不可咎。言致命遂義。殺身成仁。屬於天者雖兇。而咎則未有也。</p><p>附</p><p>頤大過四象在先天處四隅。而包滅地水火於其中。天地水火四正卦。上經首尾也。亦即離坎也。而即列於離坎之前。以結上經。最耐尋味。</p>',33)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
